from pathlib import Path
import json,csv,shutil
R=Path(__file__).resolve().parents[1]
L=[]
def lab(n,topic,slug,title,mins,goal,build,prereq,steps,prompt,checks,trouble,challenge,reflection):
 a=dict(num=n,topic=topic,slug=slug,title=title,duration=mins,goal=goal,build=build,prerequisites=prereq,steps=steps,prompt=prompt,checks=checks,troubleshooting=trouble,challenge=challenge,reflection=reflection)
 L.append(a)
lab(1,1,'grounded-campaign-brief','Create a grounded campaign brief',45,
'Produce a source-checked campaign brief for one bakery course.',
'campaign/brief.md, campaign/selected-course.json, campaign/claim-ledger.csv and campaign/unknowns.md. These define the facts used by every later asset.',
'A ChatGPT account with Work available, a browser and a text editor. Python 3 is needed only for the local website preview. Use the upload route if local folder access is unavailable.',[
('Prepare your working copy','Create a folder named C818-marketing on your computer. Copy assets/cnbacademy from this lab into it. Create a campaign folder beside cnbacademy. Do not work in the original reference folder.'),
('Start the website','In a terminal opened inside C818-marketing/cnbacademy, run python3 -m http.server 8080. Keep it running and open http://localhost:8080 in a browser. Search the course catalogue for sourdough. Confirm BAK-101 is visible. If Python is unavailable, read data/courses.json directly and use the included site screenshot in the guide.'),
('Inspect the sources','Open cnbacademy/brand.md, cnbacademy/market-brief.md and cnbacademy/data/courses.json. Locate BAK-101. Record the title, fee, weeks, when, campus, intakes, allergens and learning outcomes. These are fictional scenario facts, not real offers.'),
('Choose the access route','On ChatGPT web, create a project named C818 Marketing and add the brand, market brief and catalogue through Sources. On desktop, open Projects, create or edit a local project and attach C818-marketing using Add folder. In a new task select ChatGPT and switch to Work. If Work is unavailable, continue with the supplied checkpoint files and record the feature limitation.'),
('Set durable guidance','Add the text in assets/project-instructions.md to project instructions, or attach it as a source when the instruction editor is unavailable. Ask Work to list the sources it can actually read before continuing. A path alone does not prove access.'),
('Request the brief','Copy prompts/task.txt into the Work task. Ask for the short plan first. Check that the plan uses only BAK-101, labels unknowns and returns the four named files. Reply: Proceed with this plan; keep all outputs as classroom drafts.'),
('Review the ledger','Open claim-ledger.csv. Compare each fee, duration, schedule and location against the BAK-101 record. Add a row for remaining seats with status UNKNOWN. Confirm that class_size 12 was not treated as twelve available seats.'),
('Save and checkpoint','Download the four artifacts into C818-marketing/campaign, or confirm them on disk in the local route. Open each file. Record any corrections in unknowns.md. Keep these files for Lab 2. If the task stalled, copy this lab’s checkpoints files into campaign and label them supplied sample drafts.')],
'''Use the attached Cook & Bake Academy brand.md, market-brief.md and data/courses.json. Create a campaign brief for BAK-101 Artisan Sourdough Bread Baking aimed at weekend home bakers, with a secondary proposed cafe-business audience angle. Use no other fact sources. First propose a short plan; wait for my review before drafting.
After I approve the plan, return four files: brief.md (audience need, objective, message, CTA, scope and draft status), selected-course.json (the exact BAK-101 record), claim-ledger.csv (claim,value,source_field,status) and unknowns.md (unknown,impact,next_action). Copy source facts exactly. Record remaining seats, discounts, tax treatment, public booking link, campaign performance and sales target as UNKNOWN. A class capacity is not seats remaining. Do not add a cafe course. Do not publish, post or send anything.''' ,
['The saved selected-course.json has code BAK-101, fee 680, weeks 4 and campus Orchard Road.','The brief identifies one audience need and one primary CTA.','Every offer fact has a source_field; missing details are UNKNOWN.','All four files open and are labelled classroom draft.'],
[('Work cannot find local files','Use the project Sources upload route; attach the exact three files, then ask for the visible source list again.'),('The website is blank or courses do not load','Serve from the cnbacademy folder, not its parent, and use http://localhost:8080 rather than file://. Use port 8081 if 8080 is occupied.'),('Work invents an offer','Name the unsupported sentence, request its removal and compare the regenerated ledger with the catalogue.')],
'Repeat the brief for BAK-107, keeping a separate folder and ledger so its three-week duration cannot leak into the BAK-101 campaign.',
'Which facts came from the catalogue, and which parts of your brief are proposals?')
lab(2,1,'reusable-marketing-workflow','Build a reusable marketing workflow',50,
'Create and trial a source-grounded production playbook for the campaign.',
'campaign/workflow.md, campaign/brand-check.md and campaign/workflow-trial.md. The playbook carries the same rules into flyer, social and email production.',
'Lab 1 campaign files. This lab includes adapted brand-voice, flyer-design and social-post skill examples. They are reading resources until installed and enabled.',[
('Gather the current context','Open the Lab 1 brief and claim ledger. Copy assets/skills into C818-marketing/skills-examples so the brand and creative workflow examples remain together. Read brand-voice/SKILL.md before flyer-design/SKILL.md and social-post/SKILL.md.'),
('Translate the reference workflow','Write the seven stages in campaign/workflow.md: goal, plan, create, preserve context, version, prepare distribution and verify. For each stage name an input, output and check. Do not copy terminal-specific Claude commands into the Work task.'),
('Resolve the fact-source paths','In your working copy, resolve data/courses.json to cnbacademy/data/courses.json. The optional campaign/term-highlights.md is absent, so instruct Work to use the catalogue only. Do not create promotional facts just to satisfy a skill reference.'),
('Draft the reusable playbook','Attach the example skill files, brief and ledger to Work. Paste prompts/task.txt. Review the returned workflow and brand checklist. Check the exact tagline Learn it. Make it. Take it further.'),
('Choose a supported reuse route','The guaranteed classroom route is to add workflow.md to project Sources and cite it in each task. If skill creation is available, select @skill-creator in ChatGPT, ask it to package the reviewed workflow as a skill, then enable the resulting skill. Use its displayed name through an @ mention in a new task. Installation is optional; merely uploading SKILL.md does not enable automatic discovery.'),
('Run a small trial','Ask Work: Using workflow.md and the BAK-101 source record, produce a 60-word course introduction and a claim ledger, then stop for review. Save the result as workflow-trial.md. No image generation or connected email tool is needed.'),
('Inspect the trial','Check the trial for unsupported urgency, discounts, invented chef names and changed dates. Confirm the practical voice and exact course title. Record at least one specific improvement in brand-check.md, even if it is a wording choice.'),
('Save the checkpoint','Keep workflow.md and brand-check.md with the Lab 1 campaign files. Record whether you used Sources or an enabled skill. If setup stalled, copy checkpoints/workflow.md and trial it using the source-upload route.')],
'''Review the attached brand-voice, flyer-design and social-post workflow examples. Adapt them into one ChatGPT Work marketing playbook for the C818 classroom campaign. Use the BAK-101 brief and catalogue as the only offer facts. Return workflow.md with the seven-stage process, named inputs/outputs, fact checks, format rules and a stop-before-distribution boundary. Return brand-check.md covering the exact tagline, practical voice, palette, editable copy, alt text and unsupported claims. Explain how to reuse the file through project Sources; do not claim that a file is an enabled skill unless it was actually installed. Preserve UNKNOWN for absent campaign facts.''' ,
['workflow.md has seven named stages with inputs, outputs and checks.','The tagline and academy palette match the supplied brand examples.','The trial has no invented discounts, chef names or seat availability.','The reuse route is recorded accurately: uploaded source or installed skill.'],
[('The @ skill name does not appear','Use workflow.md as an uploaded source; do not claim automatic skill invocation.'),('A source path is broken','Point the task to cnbacademy/data/courses.json and remove the absent term-highlights source.'),('The trial sounds generic','Ask for one practical learner benefit from the exact learning outcomes, and remove unsupported superlatives.')],
'Create an email-only workflow extension that requires an audience rule, plain-text version, review log and a separate send approval.',
'What did the reusable workflow prevent that a one-off prompt might miss?')
lab(3,2,'flyer-design','Design an editable bakery flyer',75,
'Create an A5 flyer with source-checked copy and a complete text proof.',
'creative/sourdough/flyer-a5.pptx or another editable layout source, flyer-a5.pdf, flyer-copy.md, image-prompt.txt and text-proof.md.',
'Labs 1–2. PowerPoint, Google Slides or another layout editor with PDF export. Optional ChatGPT image generation; the supplied typographic checkpoint supports accounts without image generation.',[
('Prepare the asset folder','Create creative/sourdough inside C818-marketing. Copy this lab’s assets/design-brief.md into it. Keep the selected course and ledger attached to the Work task.'),
('Plan two visual routes','Paste prompts/task.txt into Work. Review the two proposed routes before production: finished loaf and hands at work. Choose one route and explain the decision in creative/sourdough/design-decision.md.'),
('Approve the exact copy','Ask Work to save flyer-copy.md with the title, four-week duration, S$680 scenario fee, Saturday schedule, Orchard Road campus, CTA and tagline. Compare each factual line with selected-course.json. Omit tax claims, discounts and remaining seats.'),
('Create or choose the visual','If image generation is available, request an original natural-light sourdough image with no text, faces, chef identities or logos. Save the exact prompt as image-prompt.txt and the image as sourdough-visual.png. If unavailable, use the typographic checkpoint and record no generated image used.'),
('Create the editable layout','Ask Work to create an editable A5 portrait flyer, or open PowerPoint and set Design > Slide Size > Custom Slide Size to width 14.8 cm and height 21 cm. In Google Slides use File > Page setup > Custom with the same dimensions. Use Georgia headings, a sans-serif body and the academy palette. Keep important text at least 10 mm from the trim edge.'),
('Place facts as live text','Use text boxes for every factual line rather than relying on lettering inside the generated image. Keep one primary CTA: View course details in the demo catalogue. Add classroom draft wording in a small but readable footer. Do not insert a fake QR code or a made-up public registration URL.'),
('Export and proof','Save the editable source and export PDF. Open the PDF at 100 percent. Transcribe every visible word and number into text-proof.md, including the footer. Beside each offer fact record the source field.'),
('Request a bounded correction','Attach the proof and PDF to Work. Ask it to find factual, hierarchy or readability problems. Choose one specific correction, preserve the verified facts, export again and update the proof.'),
('Save the checkpoint','Keep the editable source, PDF, copy, proof and prompt together. If the task stalled, use checkpoints/flyer-a5.pptx and its PDF as a classroom starting point and revise it against your own brief.')],
'''Using workflow.md, brand.md, selected-course.json and claim-ledger.csv, plan two A5 portrait flyer routes for Cook & Bake Academy BAK-101. Explain the hierarchy, image choice and CTA for each, then wait for my choice. After the choice, produce editable flyer copy and an editable layout file if your tools support it. Use the academy brand, not the trainer deck palette. Exact tagline: Learn it. Make it. Take it further. Keep all factual text editable, add a readable classroom draft footer and return a full text proof with source fields. Use no discount, seat scarcity, invented trainer or real booking promise. Generate imagery only if available and keep its prompt. Stop before publishing.''' ,
['The A5 page is 148 × 210 mm and essential text stays inside a 10 mm safe area.','Title, fee, duration, schedule and campus match the selected record.','The saved PDF is readable at 100 percent and has one CTA.','An editable source and complete visible-text proof exist.'],
[('Generated image text is misspelled','Generate the visual without text and use editable text boxes for all copy.'),('The facts crowd the layout','Remove nonessential prose before reducing body text; preserve the required offer facts and CTA.'),('No image tool is available','Use the included typographic checkpoint and record the limitation; the output still needs an editable source and proof.')],
'Create a second flyer for the career-changer audience without altering the course facts; explain the changed benefit emphasis.',
'How did hierarchy make the primary action easier to find?')
lab(4,2,'flyer-variants-and-review','Adapt and review the flyer variants',55,
'Produce square and story derivatives that retain the offer and remain readable.',
'creative/sourdough/flyer-square.pptx, flyer-story.pptx, their PDF or PNG proofs, variants-proof.md and design-review.csv.',
'Lab 3 A5 source and text proof. A layout editor and a browser or image viewer.',[
('Inspect the A5 proof','Open flyer-a5.pdf and flyer-copy.md. List the facts that must survive in each derivative: course identity, duration, fee, schedule, campus and one CTA. If Lab 3 stalled, use its checkpoint source.'),
('Create separate canvases','In your layout editor create a 1:1 square canvas and a 9:16 story canvas. For editable PowerPoint use custom sizes 20 × 20 cm and 18 × 32 cm. Export raster images at 1080 × 1080 and 1080 × 1920 when the tool supports exact pixels; otherwise use PDFs and record their aspect ratio.'),
('Request adaptation','Attach the A5 source or PDF, copy and ledger to Work, then paste prompts/task.txt. Ask for recomposition rather than cropping. Keep the academy colour and type rules.'),
('Recompose the square','Put the headline and course title near the top, use a short details block, and give the CTA its own region. Do not shrink the whole A5 page to a square screenshot.'),
('Recompose the story','Keep key information clear of the top and bottom interface zones. Use a conservative 10 percent top and bottom content margin for this classroom brief. Preserve a readable course identity and CTA.'),
('Inspect at practical sizes','Open the square at thumbnail size and the story at a phone-width view. Read every factual line. Check text contrast; for normal screen text use 4.5:1 and for qualifying large text use 3:1 as the minimum check. Record the colour pair and tool/method used in design-review.csv.'),
('Proof both variants','Transcribe all visible text for each format into variants-proof.md. Compare it with the A5 proof and selected-course.json. Record exact file names and any corrected line.'),
('Export and hand off','Save editable sources and proofs in creative/sourdough. Fill assets/design-review-template.csv with at least six concrete checks and a status for each. Resolve every factual defect before proceeding to Lab 5.')],
'''Adapt the reviewed A5 flyer to a square and 9:16 story format. Recompose the content for each format; preserve the BAK-101 identity, source-checked offer and academy brand. Keep one CTA and readable classroom draft wording. Return editable sources when supported, PDF or PNG proofs, a full text transcription for both variants and a review log covering source fidelity, crop, hierarchy and readability. Use no fake QR code, new offer or live booking promise.''' ,
['Square and story have the requested aspect ratios, with essential text visible.','Both variants match BAK-101’s title, S$680 fee and four-week duration.','The story’s key text is outside the classroom top/bottom margin zones.','design-review.csv records at least six reproducible checks and corrections.'],
[('The story crops the CTA','Reposition the CTA within the centre content area; do not rely on automatic fit.'),('Exported pixels differ','Use a supported image export or keep an aspect-correct PDF and note the pixel-export limitation.'),('A variant changes a fact','Copy the approved factual text block again, export and recheck the entire transcription.')],
'Create an accessible text-only companion that contains the offer and action for someone who cannot view the graphic.',
'Which elements needed recomposition rather than simple resizing?')
lab(5,3,'social-article-and-repurposing','Write a social article and platform packages',70,
'Create a useful article and two short-form adaptations from the same approved facts.',
'content/article.md, content/instagram.md, content/facebook.md and content/editorial-review.md.',
'Labs 1–4 campaign sources and flyer. Use the Lab 1 and Lab 3 checkpoints if earlier work is incomplete.',[
('Choose the article angle','Create content inside C818-marketing. Open assets/article-outline.md. Use the angle building confidence with a starter routine. The article explains choosing a structured class, not a new recipe or food-safety procedure.'),
('Request the outline','Attach workflow.md, brief.md and selected-course.json to Work. Paste prompts/task.txt and review the outline before drafting. Require three developed sections, source-checked course facts and one CTA.'),
('Draft the article','Ask Work to write 500–700 words and save article.md. Check that the introduction names a reader need, each middle section advances the idea and the conclusion earns its course-details CTA.'),
('Review claims','Highlight every course, price, date, location, outcome and availability claim. Compare them with the ledger. Remove unverified recipe guidance, fake chef quotes, learner stories and guarantees. Keep the academy’s practical voice.'),
('Create Instagram and Facebook packages','Ask Work for a distinct package for each platform. Each package has a hook under 10 words, caption under 120 words, exactly one CTA, exactly five relevant hashtags and an alt-text section. These are classroom brief rules, not platform limits.'),
('Ground the visual description','If you have an actual flyer or image, attach it and describe only what it shows. If no visual exists, mark the alt text proposed alt text and state that it describes a planned asset.'),
('Compare the adaptations','Read both captions beside the article. Keep the same central promise and offer facts, but vary the opening and format. Record three editorial checks and corrections in editorial-review.md.'),
('Save and verify','Download the four files into content. Count the article words and inspect each caption package. If drafting stalled, use checkpoints/article.md and revise it rather than presenting the sample as your reviewed work.')],
'''Plan a 500–700 word original social article for Cook & Bake Academy: Building confidence with a sourdough starter routine. Explain how structured practice supports a beginner; do not invent a recipe, trainer identity, learner testimonial or food-safety claim. Use only BAK-101 catalogue facts for the course offer. First return an outline for review. After approval, write article.md with three developed sections and one course-details CTA. Then return distinct instagram.md and facebook.md packages: hook under 10 words, caption under 120 words, one CTA, exactly five hashtags (three topical and two local), actual-image alt text or clearly labelled proposed alt text, and a claim source list. Preserve the academy voice and UNKNOWN boundaries. Do not post or schedule.''' ,
['article.md has 500–700 words, three developed sections and one CTA.','Each platform package has a hook, caption, five hashtags, alt text and claim sources.','Every offer fact agrees with the ledger; no invented chef or learner testimonial appears.','editorial-review.md records at least three specific checks and revisions.'],
[('The article is a sales list','Ask for a reader problem, explanatory middle and practical decision guidance; place the course offer in one concise block.'),('The captions are identical','Ask for a different opening and emphasis while preserving the central promise and offer.'),('Alt text describes a nonexistent photo','Attach the actual visual or mark the description proposed alt text.')],
'Create a five-panel carousel outline, with one idea per panel and no new offer facts.',
'What stayed consistent when the article became a short caption?')
lab(6,3,'content-calendar-and-quality','Build a content calendar and editorial gate',60,
'Create a five-post calendar with sources, dependencies and review status.',
'content/calendar.csv, content/posts.md and content/content-review.csv.',
'Lab 5 article and caption packages. The supplied calendar template provides a recovery route.',[
('Load the calendar template','Copy assets/calendar-template.csv to content/calendar.csv. Use Day 1, Day 3, Day 5, Day 7 and Day 9 rather than real publication dates. The plan is hypothetical and unscheduled.'),
('Select five angles','Choose three teaching angles, one practical question and one direct course invitation. Label the last one hard_sell = yes and the other four no. Keep the same BAK-101 campaign spine.'),
('Request the calendar','Attach the article, platform packages and workflow to Work, then paste prompts/task.txt. Require asset names, source fields, audience, CTA, owner, dependency and status for every row.'),
('Draft the five post packages','Ask Work to produce posts.md with the five rows expanded into full hook, caption, five hashtags, alt text and claim sources. Each caption stays under 120 words with one CTA.'),
('Review the dependencies','Link each post to its article or flyer asset. Use owner = classroom marketer and status = draft for every item. If an image is missing, mark its dependency unresolved rather than claiming it is ready.'),
('Check the promotional balance','Count hard_sell = yes rows; the expected count is one out of five. This is the academy’s reused brand rule. Check that the other four provide useful context and do not merely hide sales language.'),
('Run the editorial gate','Fill content-review.csv from assets/content-review-template.csv. Check audience relevance, source fidelity, CTA count, hashtag count, alt text and draft status for all five posts. Record at least one substantive revision.'),
('Save the checkpoint','Keep calendar.csv, posts.md and content-review.csv together. No post is scheduled or published. Use checkpoints/calendar.csv if planning stalled, then add your own reviewed assets and issue notes.')],
'''Using the reviewed BAK-101 article and platform packages, create a hypothetical five-post content plan on Day 1, Day 3, Day 5, Day 7 and Day 9. Use three teaching posts, one practical question and one direct invitation, with at most one hard-sell post. Return calendar.csv with day,platform,pillar,audience,asset,source,cta,owner,dependency,status,hard_sell. Return posts.md containing five complete short-form packages using the same classroom caption rules. Use only verified catalogue facts. Label missing visual descriptions proposed alt text and keep all rows draft. Do not schedule or publish.''' ,
['calendar.csv has five rows and one hard_sell = yes row.','Every row has a source, asset, owner, dependency and draft status.','Each post package has one CTA and five hashtags.','The review log contains specific evidence and at least one substantive revision.'],
[('All five posts sell the course','Rewrite four as useful teaching or preparation angles; retain only one direct invitation.'),('Calendar paths do not exist','Use the exact saved asset name or mark the dependency unresolved.'),('Work schedules real dates','Replace dates with relative Day labels and stop connected scheduling actions.')],
'Add a sixth response post that answers a reader question while preserving the one-in-five promotional rule for the first five posts.',
'How does the calendar help another marketer continue the campaign?')
lab(7,4,'email-sequence-and-segmentation','Prepare a segmented email campaign',85,
'Build an unsent three-email sequence for an explicitly eligible synthetic audience.',
'email/sequence.md, email/email-1.html, email/email-1.txt, email/segment.csv and email/send-checklist.md.',
'Labs 1–6 sources. A spreadsheet or Work data-analysis tools for the synthetic CSV; a browser for HTML preview. No real email platform or subscriber list is required.',[
('Prepare synthetic data','Create email inside C818-marketing. Copy assets/contacts.csv into email/contacts.csv. Open the CSV and confirm every address ends in example.com. These are invented contacts.'),
('Define the eligibility rule','Write in send-checklist.md: consent = yes AND interest = bakery AND suppressed = no. Missing consent is excluded. This is a classroom rule; real production requirements need organisational review.'),
('Filter and inspect','In a spreadsheet filter all three criteria, or ask Work to apply the rule to the CSV and return segment.csv. The expected IDs are C001, C004 and C006. Check each included and excluded row manually.'),
('Plan the sequence','Attach the brief, course record and segment to Work. Paste prompts/task.txt. Review the introduction, clarification and reminder roles with proposed timing Day 1, Day 4 and Day 8. Do not invent an intake deadline or limited-seat claim.'),
('Draft all three messages','After approving the plan, request sequence.md with a subject, preheader, body, one CTA and a neutral name fallback for each message. Keep a practical voice and scenario-only course facts.'),
('Create a preview for Email 1','Ask Work to produce email-1.html as a simple single-column, 600 px maximum-width layout and email-1.txt with the same meaning. The HTML link uses https://example.com/courses/BAK-101 with utm_source=email, utm_medium=newsletter, utm_campaign=sourdough_oct_demo and utm_content=e1_a. Label the destination as a demo.'),
('Review placeholders','Use a clearly labelled demo unsubscribe placeholder in the HTML and a provider-configuration note in send-checklist.md. Record production sender, physical address, live booking destination and unsubscribe setup as UNKNOWN. Do not substitute the academy’s fictional campus for an unverified sender address.'),
('Preview and correct','Open email-1.html in a browser at desktop and 375 px width. Confirm the course facts are live text, the CTA is visible, the layout does not scroll horizontally and the plain-text version carries the same offer. This is a content preview, not a real inbox test.'),
('Save the unsent checkpoint','Store all five deliverables. Mark send-checklist.md classroom draft — not sent. If the task stalled, use checkpoints/email-1.html and sequence.md, then verify the segment using the supplied CSV.')],
'''Create an unsent three-email campaign for Cook & Bake Academy BAK-101 using only the reviewed campaign sources. First propose the sequence roles and relative timing for review. Apply consent=yes AND interest=bakery AND suppressed=no to contacts.csv and return segment.csv without adding anyone. After plan approval return sequence.md with introduction, clarification and reminder messages, each with subject, preheader, body, one CTA and a neutral name fallback. Return email-1.html and equivalent email-1.txt. Use a simple single-column layout, live text facts and an example.com demo CTA with the supplied UTM taxonomy. Use a labelled demo unsubscribe placeholder. Return send-checklist.md listing production sender, sender address, real booking link and provider unsubscribe setup as UNKNOWN. No actual upload, scheduling or send is authorised.''' ,
['segment.csv contains exactly C001, C004 and C006, with all three rule fields satisfied.','sequence.md has three distinct message roles and no invented urgency.','Email 1 HTML and text versions carry the same source-checked facts.','The HTML preview fits 375 px width and the checklist states not sent.'],
[('A suppressed contact is included','Reapply all three criteria with AND, not OR, and inspect each row.'),('A merge field appears literally','Use the neutral fallback in the preview; configure real platform tags only during a separate production setup.'),('A real email tool tries to send','Stop the action and export the draft files only; no live send is part of this lab.')],
'Create a subject-line B variant while keeping body, audience rule, CTA and timing fixed; document the hypothesis.',
'Why must recipient eligibility be checked before the copy is written?')
lab(8,4,'measurement-and-campaign-handoff','Measure and hand off the campaign',50,
'Interpret synthetic results and package a source-checked, reviewable campaign handoff.',
'campaign/metrics.csv, campaign/recommendation.md, campaign/manifest.csv and campaign/handoff.md.',
'Labs 1–7 current assets. Synthetic assets/campaign-results.csv is supplied; no live campaign analytics or real business results are required.',[
('Load the synthetic results','Copy assets/campaign-results.csv into campaign/campaign-results.csv. Read the definitions in assets/metric-definitions.md. Counts are invented teaching data and are not academy performance.'),
('Calculate clearly defined rates','Ask Work or a spreadsheet to calculate delivery_rate = delivered/sent, click_rate = unique_clicks/delivered and click_to_booking = bookings/unique_clicks. Save campaign/metrics.csv with numerator, denominator and rate. If a denominator is zero, use UNKNOWN rather than dividing by zero.'),
('Verify the arithmetic','Variant A has 1000 sent, 980 delivered, 49 unique clicks and 7 bookings. Confirm 98.0 percent delivery, 5.0 percent click rate and 14.3 percent click-to-booking conversion. Variant B has 1000 sent, 975 delivered, 58 unique clicks and 8 bookings; confirm 97.5 percent, about 5.95 percent and about 13.79 percent.'),
('Request a bounded recommendation','Attach metrics.csv and the campaign brief to Work and paste prompts/task.txt. Separate observation, limitation and proposed next test. A higher rate in this sample does not establish a reliable lift.'),
('Inventory current files','Copy assets/manifest-template.csv to campaign/manifest.csv. Add the current flyer sources and proofs, article, platform packages, calendar, sequence, segment and metrics. Record path, purpose, version, source, status and unresolved issue for each.'),
('Cross-check the campaign','Open one flyer proof, article and email beside selected-course.json. Check BAK-101, four weeks, S$680 and the same academy identity. Check calendar and email status remain draft. Record specific evidence in handoff.md.'),
('Resolve or assign holds','List missing production sender, public booking link, unsubscribe configuration and launch target as UNKNOWN with an owner and next action. Do not label the campaign production-ready while these holds remain.'),
('Package and explain','Save the four deliverables and explain your recommendation to a partner using the metrics and manifest. Keep the package as a classroom draft. If previous labs stalled, use their checkpoint files, record sample provenance and continue the handoff without claiming you generated them.')],
'''Analyze campaign-results.csv as synthetic teaching data. Calculate delivery rate, unique click rate and click-to-booking conversion with explicit numerators and denominators. Return metrics.csv and recommendation.md with observations, limitations and one proposed controlled next test. Do not claim statistically reliable uplift, revenue or real academy results. Build manifest.csv and handoff.md for the current campaign files, recording versions, source facts, review evidence and unresolved production holds. Keep sender, real booking link, unsubscribe configuration and launch target UNKNOWN unless supplied. Confirm that no campaign message was sent or scheduled.''' ,
['A rates are 98.0%, 5.0% and approximately 14.3%; B rates are 97.5%, approximately 5.95% and 13.79%.','The recommendation distinguishes synthetic observation from a proposed test.','Every manifest path points to a current file or is explicitly unresolved.','The handoff records facts checked, remaining UNKNOWNs and draft/not-sent status.'],
[('The click rate uses sent as denominator','Use delivered for this exercise’s unique click rate and show the denominator column.'),('Work claims a reliable winner','Ask for the sample limitation and a proposed next test; remove unsupported causal or statistical claims.'),('The manifest lists missing files','Correct the paths or label unresolved; use the supplied checkpoint only with its provenance recorded.')],
'Add a zero-delivery row and prove the rate is UNKNOWN; propose what operational investigation would be needed before interpreting it.',
'What evidence would be needed before using this recommendation for a real launch?')
(R/'data/labs.json').write_text(json.dumps(L,indent=2,ensure_ascii=False))
for a in L:
 p=R/'labs'/f"lab-{a['num']:02d}-{a['slug']}";p.mkdir(parents=True,exist_ok=True)
 for d in ['assets','prompts','checkpoints']:(p/d).mkdir(exist_ok=True)
 (p/'prompts/task.txt').write_text(a['prompt']+'\n')
